import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';

export async function runMotionUploadSmoke(page){
 const previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));
 const dir=await fs.mkdtemp(path.join(os.tmpdir(),'nagweb-motion-images-'));
 const files={a:path.join(dir,'Personal-A.svg'),b:path.join(dir,'Personal-B.svg'),late:path.join(dir,'Tardia.svg'),bad:path.join(dir,'Invalida.txt')};
 for(const key of ['a','b','late'])await fs.writeFile(files[key],`<svg xmlns="http://www.w3.org/2000/svg" width="300" height="180"><rect width="300" height="180" fill="${key==='a'?'tomato':'royalblue'}"/><text x="12" y="40">${key}</text></svg>`);
 await fs.writeFile(files.bad,'Esto no es una imagen');
 try{
  await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,elements:[]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});
  const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY),assets:project.assets.images.length}));
  async function ready(name){await page.waitForFunction(name=>{const lab=document.querySelector('.nw-motion-dialog'),field=lab.querySelector('[data-motion-content="0"]'),image=lab.querySelector('iframe')?.contentDocument?.querySelector('.im-hov img');return !lab.querySelector('[data-motion-upload="0"]').disabled&&(!name||field.selectedOptions[0].textContent===name)&&image?.complete&&image.naturalWidth>0&&(!name||(image.naturalWidth===300&&image.naturalHeight===180));},{timeout:10000},name);}
  async function open(gid){if(gid)await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),gid);else await page.click('.tb-left [data-motion-open]');await ready();}
  async function upload(key,chooser=false){await page.click('[data-motion-library-tab="elements"]');const id=await page.$eval('[data-motion-layer]',n=>n.dataset.motionLayer);await page.click('[data-motion-layer="'+id+'"]');if(chooser){const chosen=page.waitForFileChooser();await page.click('[data-motion-image-preview="0"]');await (await chosen).accept([files[key]]);}else await (await page.$('[data-motion-upload="0"]')).uploadFile(files[key]);await ready(path.basename(files[key]));await page.waitForFunction(id=>{const a=document.querySelector('[data-motion-layer="'+id+'"] img'),b=document.querySelector('[data-motion-image-preview="0"] img');return a?.complete&&a.naturalWidth===300&&b?.complete&&b.naturalWidth===300&&a.getAttribute('src')===b.getAttribute('src');},{},id);assert.equal(await page.$eval('[data-motion-image-preview="0"] [data-motion-image-name]',n=>n.textContent),path.basename(files[key]));await page.click('[data-motion-library-tab="library"]');}
  await open();await upload('a',true);assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);await page.click('[data-motion-close]');assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);
  await open();await upload('a');await upload('b');const preparedId=await page.$eval('[data-motion-content="0"]',n=>n.value);
  await (await page.$('[data-motion-upload="0"]')).uploadFile(files.bad);await ready('Personal-B.svg');assert.equal(await page.$eval('[data-motion-content="0"]',n=>n.value),preparedId,'Invalid image keeps previous selection');
  await page.click('[data-motion-template="soft-orbit"]');await page.waitForFunction(()=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('.hd')?.textContent==='Diseño en movimiento.');await page.click('[data-motion-template="iso-focus"]');await ready('Personal-B.svg');
  assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>history.length),0);
  await page.click('[data-motion-insert-group]');
  const inserted=await page.evaluate(()=>({project:JSON.stringify(project),group:sec().elements.find(e=>e.nwMotionInstance),images:sec().elements.filter(e=>e.type==='image'),assets:project.assets.images}));
  assert.equal(inserted.images[0].assetId,preparedId);assert.equal(inserted.assets.length,before.assets+3,'Only the three used images are committed');assert.equal(inserted.assets.some(a=>a.name==='Personal-A.svg'),false);assert.equal(inserted.assets.find(a=>a.id===preparedId).name,'Personal-B.svg');assert.equal(inserted.images[0].x,23);assert.equal(inserted.images[0].w,23);assert.equal(JSON.parse(inserted.project).pages[0].sections[0].sdEnabled,false);
  await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);
  await open(inserted.group.id);await upload('a');await upload('b');const savedId=await page.$eval('[data-motion-content="0"]',n=>n.value);await page.click('[data-motion-save]');
  const saved=await page.evaluate(id=>({project:JSON.stringify(project),groupCount:sec().elements.filter(e=>e.nwMotionInstance).length,image:sec().elements.find(e=>e.id===id),assets:project.assets.images}),inserted.images[0].id);
  assert.equal(saved.image.assetId,savedId);assert.equal(saved.assets.length,inserted.assets.length+1);assert.equal(saved.assets.some(a=>a.name==='Personal-A.svg'),false);assert.equal(saved.groupCount,1);const original={...inserted.images[0],assetId:savedId};assert.deepEqual(saved.image,original,'Replacement preserves geometry, ID, mobile settings and moments');
  await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);
  await open(inserted.group.id);await ready('Personal-B.svg');
  await page.evaluate(()=>{window.motionNativeReader=FileReader;window.FileReader=class extends FileReader{readAsDataURL(file){setTimeout(()=>super.readAsDataURL(file),500);}};});
  await (await page.$('[data-motion-upload="0"]')).uploadFile(files.late);assert.equal(await page.$eval('[data-motion-save]',n=>n.disabled),true);await page.click('[data-motion-close]');await page.evaluate(()=>{window.FileReader=window.motionNativeReader;delete window.motionNativeReader;});await open();
  await page.waitForFunction(()=>!document.querySelector('[data-motion-upload="0"]').disabled);await new Promise(r=>setTimeout(r,700));assert.equal(await page.$$eval('[data-motion-content="0"] option',ns=>ns.some(n=>n.textContent==='Tardia.svg')),false,'Late completion cannot enter a new session');assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);await page.click('[data-motion-close]');
  await page.evaluate(()=>{const f=document.createElement('iframe');f.id='upload-export';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});
  await page.waitForFunction(id=>{const image=document.querySelector('#upload-export')?.contentDocument?.querySelector('[data-id="'+id+'"] img');return image?.complete&&image.naturalWidth===300&&image.naturalHeight===180;},{timeout:10000},saved.image.id);
  console.log('Imágenes propias Motion Lab: selector de archivos, preview, rechazo sin pérdida, cerrar, borradores, solo recursos usados, inserción y guardado en misma instancia, geometría/momentos, historial, carga tardía y exportación OK');
 }finally{
  await page.evaluate(p=>{if(window.motionNativeReader){window.FileReader=window.motionNativeReader;delete window.motionNativeReader;}document.querySelector('.nw-motion-dialog').close();document.querySelector('#upload-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);await fs.rm(dir,{recursive:true,force:true});
 }
}
